/* Auto-expiry: hide any leg whose date has passed. Outdated legs break client trust,
   so this filters on every page load - a leg vanishes the day after it departs. */
(function(){var d=new Date();var t=d.getFullYear()*10000+(d.getMonth()+1)*100+d.getDate();
 window.EMPTY_LEGS=_EL_ALL.filter(function(l){return (l.sk||0)>=t;});})();

/* show-all: localized empty-leg pages paginate at 24; expand them automatically.
   Harmless where there is no Show-more button (EN /empty-legs already shows all). */
(function(){function go(){var t=0;var iv=setInterval(function(){var b=document.getElementById('elMore');t++;
if(!b||t>40){clearInterval(iv);return;}
if(b.classList.contains('hide')){clearInterval(iv);return;}
for(var i=0;i<200&&!b.classList.contains('hide');i++){b.click();}
clearInterval(iv);},60);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',go);else go();})();
